#!/usr/bin/env python3
"""Generate one bounded ordinary movement leg with a measured buried ending."""
import argparse,pathlib,subprocess,sys
p=argparse.ArgumentParser();p.add_argument('x',type=int);p.add_argument('z',type=int);p.add_argument('--ms',type=int,default=25000);p.add_argument('--tag',required=True);a=p.parse_args();d=pathlib.Path('tasks/minecraft/team/p2/iter32')
body=r'''
console.log('SOURCE',JSON.stringify({...state(),faces:boundary(),time:bot.time.timeOfDay}));let dead=false;const die=()=>{dead=true;stop();};const health=()=>console.log('HEALTH_EVENT',JSON.stringify({...state(),near:Object.values(bot.entities).filter(e=>e.position.distanceTo(bot.entity.position)<12&&['zombie','skeleton','creeper','spider','arrow'].includes(e.name)).map(e=>({n:e.name,p:e.position}))}));bot.on('death',die);bot.on('health',health);const src=bot.entity.position.clone();let reason='budget';
try{if(!boundary().every(f=>f.full)||bot.health<12||!bot.inventory.items().some(i=>i.name==='stone_pickaxe'))throw Error('current capability');await exitShelter();await bot.equip(bot.inventory.items().find(i=>i.name==='stone_sword'),'hand');
const m=new Movements(bot);m.canDig=false;m.allowParkour=false;m.allow1by1towers=false;m.allowSprinting=false;m.maxDropDown=1;m.infiniteLiquidDropdownDistance=false;m.scafoldingBlocks=[];m.scaffoldingBlocks=[];for(const n of['water','lava','powder_snow','sweet_berry_bush'])m.blocksToAvoid.add(bot.registry.blocksByName[n].id);m.exclusionAreasStep.push(b=>['water','lava','powder_snow','sweet_berry_bush'].includes(b.name)?Infinity:0);m.exclusionAreasStep.push(b=>Object.values(bot.entities).some(e=>['zombie','skeleton','creeper','witch','spider'].includes(e.name)&&Math.abs(e.position.y-b.position.y)<3&&Math.hypot(e.position.x-b.position.x,e.position.z-b.position.z)<16)?Infinity:0);bot.pathfinder.setMovements(m);const goal=new goals.GoalNearXZ(GOALX,GOALZ,2);bot.pathfinder.setGoal(goal);const t=Date.now();while(Date.now()-t<LEGMS&&!goal.isEnd(bot.entity.position.floored())&&!dead&&bot.health>12){const close=Object.values(bot.entities).some(e=>['spider','zombie','skeleton'].includes(e.name)&&e.position.distanceTo(bot.entity.position)<2.8);if(close){stop();const hits=await defend(2400);console.log('LIVE_DEFENSE_RESULT',JSON.stringify({hits,state:state()}));if(bot.health>12)bot.pathfinder.setGoal(goal);}await wait(2);}stop();await wait(5);reason=dead?'death':bot.health<=12?'health':goal.isEnd(bot.entity.position.floored())?'arrived':'budget';console.log('TRAVEL_EFFECT',JSON.stringify({...state(),reason,distance:bot.entity.position.distanceTo(src),target:{x:GOALX,z:GOALZ}}));if(dead)throw Error('death');await finishShelter();const healStart=Date.now();while(Date.now()-healStart<5000){const b=bot.inventory.items().find(i=>i.name==='sweet_berries');if(b&&bot.food<20){await bot.equip(b,'hand');await bot.consume();await wait(12);}else break;}console.log('RETAINED_FOOD_USE',JSON.stringify({...state(),faces:boundary()}));
}catch(e){console.log('FAILURE',String(e),JSON.stringify(state()));if(!dead)try{if(!boundary().every(f=>f.full))await finishShelter();}catch(x){console.log('RECOVERY_FAILURE',String(x),JSON.stringify(state()));}}finally{stop();bot.removeListener('death',die);bot.removeListener('health',health);}return {...state(),dead,reason,faces:boundary(),kind:global.p2ShelterKind};
'''.replace('GOALX',str(a.x)).replace('GOALZ',str(a.z)).replace('LEGMS',str(a.ms))
f=d/(a.tag+'.js');f.write_text((d/'core.js').read_text()+(d/'ending.js').read_text()+(d/'defense.js').read_text()+(d/'box.js').read_text()+(d/'exit_shelter.js').read_text()+body)
sys.exit(subprocess.call([sys.executable,str(d/'run_p2.py'),'--timeout',str(a.ms//1000+35),'--out',str(d/(a.tag+'.out')),str(f)]))
